-- Store rows only. Book content is generated by `npm run import:book` (see README).
insert into public.stores
  (slug, name, tagline, description, primary_color, secondary_color, background_color, text_color, font, price_cents, currency)
values
  ('cocteles', 'Cócteles para tus fiestas',
   'Recetas fáciles para lucirte en casa',
   'Un recetario de cócteles clásicos y colombianos, con medidas claras y qué dejar listo antes de que lleguen tus invitados.',
   '#7c2d12', '#f59e0b', '#fffbeb', '#1c1917', 'Playfair Display', 1990000, 'COP'),
  ('micheladas', 'Micheladas y cervezas preparadas',
   'Prepara en casa para tus reuniones',
   'Micheladas, cheladas y cervezas preparadas organizadas por categoría, con medidas, qué se adelanta y consejos de consumo responsable.',
   '#b91c1c', '#facc15', '#fff7ed', '#1f2937', 'Poppins', 1990000, 'COP')
on conflict (slug) do update set
  name = excluded.name, tagline = excluded.tagline, description = excluded.description,
  primary_color = excluded.primary_color, secondary_color = excluded.secondary_color,
  background_color = excluded.background_color, text_color = excluded.text_color,
  font = excluded.font, price_cents = excluded.price_cents, currency = excluded.currency;
